mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.z += time * 0.9;
  vec3 c = abs(mod(p, 2.0) - 1.0);
  float sx = length(c.yz) - 0.08;
  float sy = length(c.xz) - 0.08;
  float sz = length(c.xy) - 0.08;
  float node = length(c) - 0.18;
  return min(min(sx, sy), min(sz, node));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -1.0);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 14.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.02, 0.01, 0.04);
  if (t < 14.0) {
    float fog = 1.0 / (1.0 + t * t * 0.03);
    col = vec3(0.8, 0.2, 1.0) * fog * (1.0 + 0.3 * bass);
  }
  ret = col;
}
